import functools

def timer(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        print(f'函数 {func.__name__} 返回 {result}')
        return result
    return wrapper


def retry(times=3):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last = None
            for _ in range(times):
                try:
                    return func(*args, **kwargs)
                except Exception as exc:
                    last = exc
            raise last
        return wrapper
    return decorator


@timer
def add(a, b):
    return a + b


calls = {'n': 0}

@retry(times=3)
