def dec_to_base(n, base):
    digits = '0123456789ABCDEF'
    if n == 0:
        return '0'
    stack = []
    while n > 0:
        stack.append(n % base)
        n //= base
    out = []
    while stack:
        out.append(digits[stack.pop()])
    return ''.join(out)

