def matrix_to_adjlist(matrix):
    adjlist = {}
    for i in range(len(matrix)):
        neighbors = []
        for j in range(len(matrix[i])):
            if matrix[i][j] != 0:
                neighbors.append(j)
        adjlist[i] = neighbors
    return adjlist

def count_edges(adjlist):
    total = 0
    for neighbors in adjlist.values():
        total += len(neighbors)
    return total // 2

