solution:
from collections import deque

def bfs_shortest(graph, start):
    if not graph or start not in graph:
        return {}
    dist = {start: 0}
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

